// The name learners see (Setting coachName), trimmed and at most 60 characters; '' when none is set,
// and the words then say "your coach". Public: the name only, never an address or anything else.
(async () => {
  try {
    const rows = await Noodl.Records.query('Setting', { key: { equalTo: 'coachName' } }, { limit: 2, plain: true });
    Outputs.name = rows[0] ? String(rows[0].value || '').replace(/\s+/g, ' ').trim().slice(0, 60) : '';
    Outputs.done();
  } catch (e) {
    console.error('[dbu:coachName]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
